require_once __DIR__.'/lib/auth.php';requireAuth();require_once __DIR__.'/lib/workspace.php';
function cleanJobHtml(string $html):string{$html=strip_tags($html,'<p><br><strong><b><em><i><ul><ol><li><h2><h3><blockquote><a>');$html=preg_replace('/\s+on\w+\s*=\s*("[^"]*"|\'[^\']*\'|[^\s>]+)/iu','',$html);$html=preg_replace('/href\s*=\s*(["\'])\s*javascript:[^"\']*\1/iu','href="#"',$html);return trim($html);}
$pdo=db();$id=(int)($_GET['id']??$_POST['id']??0);$job=['id'=>0,'title'=>'','description'=>'<p>Describe the role, responsibilities and impact.</p>','public_url'=>'','location'=>'','employment_type'=>'Full-time','min_experience'=>'','max_experience'=>'','minimum_commitment_months'=>'','required_skills_json'=>'[]','preferred_skills_json'=>'[]','status'=>'draft'];$message='';
if($id){$s=$pdo->prepare('SELECT * FROM jobs WHERE id=?');$s->execute([$id]);$job=$s->fetch()?:$job;}
if($_SERVER['REQUEST_METHOD']==='POST'&&verifyCsrf($_POST['csrf']??'')){$required=array_values(array_unique(array_filter(array_map('trim',preg_split('/[,\r\n]+/',$_POST['required_skills']??'')))));$preferred=array_values(array_unique(array_filter(array_map('trim',preg_split('/[,\r\n]+/',$_POST['preferred_skills']??'')))));$description=cleanJobHtml($_POST['description']??'');$values=[trim($_POST['title']),$description,trim($_POST['location'])?:null,trim($_POST['employment_type'])?:null,$_POST['min_experience']!==''?$_POST['min_experience']:null,$_POST['max_experience']!==''?$_POST['max_experience']:null,$_POST['minimum_commitment_months']!==''?(int)$_POST['minimum_commitment_months']:null,json_encode($required),json_encode($preferred),$_POST['status']];if($id){$values[]=$id;$pdo->prepare('UPDATE jobs SET title=?,description=?,location=?,employment_type=?,min_experience=?,max_experience=?,minimum_commitment_months=?,required_skills_json=?,preferred_skills_json=?,status=? WHERE id=?')->execute($values);}else{$pdo->prepare('INSERT INTO jobs(title,description,location,employment_type,min_experience,max_experience,minimum_commitment_months,required_skills_json,preferred_skills_json,status) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute($values);$id=(int)$pdo->lastInsertId();}$pdo->prepare('INSERT INTO wishlist_profiles(user_id,job_id,name,required_skills_json) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE job_id=VALUES(job_id),required_skills_json=VALUES(required_skills_json)')->execute([currentUser()['id'],$id,trim($_POST['title']),json_encode($required)]);$message='Job saved.';$s=$pdo->prepare('SELECT * FROM jobs WHERE id=?');$s->execute([$id]);$job=$s->fetch();}
$required=json_decode($job['required_skills_json']??'[]',true)?:[];$preferred=json_decode($job['preferred_skills_json']??'[]',true)?:[];$description=cleanJobHtml($job['description']??'');$activePage='dashboard';$pageTitle=($id?'Edit':'Create').' job · ResumeIQ';$pageStyles='<link rel="stylesheet" href="https://cdn.ckeditor.com/ckeditor5/48.5.2/ckeditor5.css"><style>.workspace{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(330px,.85fr);gap:10px;margin-top:10px;align-items:start}.preview{padding:28px;position:sticky;top:84px;min-height:680px}.preview-head{padding-bottom:20px;border-bottom:1px solid var(--line)}.preview h1{font-size:30px;margin:8px 0}.meta,.skills{display:flex;gap:7px;flex-wrap:wrap}.meta{color:var(--muted);font-size:11px}.preview-copy{font-size:13px;line-height:1.75;margin-top:22px}.preview-section{margin-top:22px}.preview-section h3{font-size:12px;text-transform:uppercase;letter-spacing:.06em}.editor{padding:16px}.field{margin-bottom:11px}.field label{display:block;font-size:10px;color:var(--muted);margin-bottom:5px}.twocol{display:grid;grid-template-columns:1fr 1fr;gap:8px}.readonly{background:#f4f4f7;color:#777}.ck-editor__editable{min-height:220px}.savebar{display:flex;gap:8px;position:sticky;bottom:8px;background:#fff;padding-top:10px}.hint{font-size:9px;color:var(--muted);margin-top:4px}@media(max-width:950px){.workspace{grid-template-columns:1fr}.preview{position:static;min-height:0}}</style>';require __DIR__.'/views/partials/header.php';?>
<section class="page-head"><div><div class="kicker">Job publishing workspace</div><h1><?=$id?'Edit job':'Create job'?></h1><p>Live candidate-facing preview on the left; job controls on the right.</p></div><a class="btn" href="dashboard.php#jobs">Back to jobs</a></section><?php if($message):?><div class="panel" style="padding:10px;color:var(--green);margin-top:10px"><?=htmlspecialchars($message)?></div><?php endif?>
<section class="workspace"><article class="panel preview"><div class="preview-head"><div class="kicker" id="pvStatus"><?=htmlspecialchars($job['status'])?> role</div><h1 id="pvTitle"><?=htmlspecialchars($job['title']?:'Untitled job')?></h1><div class="meta"><span id="pvLocation"><?=htmlspecialchars($job['location']?:'Location not set')?></span><span>·</span><span id="pvType"><?=htmlspecialchars($job['employment_type']?:'Employment type not set')?></span><span>·</span><span id="pvExperience"><?=htmlspecialchars(($job['min_experience']!==null?$job['min_experience']:'0').'–'.($job['max_experience']!==null?$job['max_experience']:'∞'))?> years</span></div></div><div class="preview-copy" id="pvDescription"><?=$description?></div><div class="preview-section"><h3>Required skills</h3><div class="skills" id="pvRequired"><?php foreach($required as $skill):?><span class="tag"><?=htmlspecialchars($skill)?></span><?php endforeach?></div></div><div class="preview-section"><h3>Preferred skills</h3><div class="skills" id="pvPreferred"><?php foreach($preferred as $skill):?><span class="tag"><?=htmlspecialchars($skill)?></span><?php endforeach?></div></div><div class="preview-section"><h3>Expected commitment</h3><p id="pvCommitment"><?=$job['minimum_commitment_months']?(int)$job['minimum_commitment_months'].' months minimum':'Not specified'?></p></div></article>
<form class="panel editor" method="post" id="jobForm"><input type="hidden" name="csrf" value="<?=csrfToken()?>"><input type="hidden" name="id" value="<?=$id?>"><div class="field"><label>Job title</label><input class="control live" data-preview="pvTitle" name="title" required value="<?=htmlspecialchars($job['title'])?>"></div><div class="twocol"><div class="field"><label>Status</label><select class="control" id="status" name="status"><?php foreach(['draft','open','paused','closed'] as $value):?><option <?=$job['status']===$value?'selected':''?>><?=$value?></option><?php endforeach?></select></div><div class="field"><label>Employment type</label><input class="control live" data-preview="pvType" name="employment_type" value="<?=htmlspecialchars($job['employment_type']??'')?>"></div></div><div class="field"><label>Location</label><input class="control live" data-preview="pvLocation" name="location" value="<?=htmlspecialchars($job['location']??'')?>"></div><div class="twocol"><div class="field"><label>Min experience</label><input class="control" id="minExperience" type="number" min="0" step="0.5" name="min_experience" value="<?=htmlspecialchars($job['min_experience']??'')?>"></div><div class="field"><label>Max experience</label><input class="control" id="maxExperience" type="number" min="0" step="0.5" name="max_experience" value="<?=htmlspecialchars($job['max_experience']??'')?>"></div></div><div class="field"><label>Expected minimum commitment (months)</label><input class="control" id="commitment" type="number" min="0" max="120" name="minimum_commitment_months" value="<?=htmlspecialchars($job['minimum_commitment_months']??'')?>"><div class="hint">Recruiter-defined expectation only; never used to predict loyalty or auto-reject.</div></div><div class="field"><label>Required skills</label><textarea class="control" id="requiredSkills" name="required_skills" rows="3"><?=htmlspecialchars(implode(', ',$required))?></textarea></div><div class="field"><label>Preferred skills / benefits</label><textarea class="control" id="preferredSkills" name="preferred_skills" rows="3"><?=htmlspecialchars(implode(', ',$preferred))?></textarea></div><div class="field"><label>Public job URL</label><input class="control readonly" readonly value="<?=htmlspecialchars($job['public_url']?:'Generated/synced after publishing')?>"><div class="hint">Public link is system-managed and cannot be manually edited.</div></div><div class="field"><label>Rich job description</label><textarea id="description" name="description"><?=$description?></textarea></div><div class="savebar"><button class="btn btn-primary">Save job</button><?php if($job['public_url']):?><a class="btn" target="_blank" rel="noopener" href="<?=htmlspecialchars($job['public_url'])?>">Open public page</a><?php endif?></div></form></section>
<script src="https://cdn.ckeditor.com/ckeditor5/48.5.2/ckeditor5.umd.js"></script><script>const escapeHtml=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c])),renderSkills=(id,value)=>document.getElementById(id).innerHTML=value.split(/[,\n]+/).map(x=>x.trim()).filter(Boolean).map(x=>'<span class="tag">'+escapeHtml(x)+'</span>').join('');document.querySelectorAll('.live').forEach(x=>x.oninput=()=>document.getElementById(x.dataset.preview).textContent=x.value||'Not set');const experience=()=>pvExperience.textContent=(minExperience.value||0)+'–'+(maxExperience.value||'∞')+' years';minExperience.oninput=maxExperience.oninput=experience;commitment.oninput=()=>pvCommitment.textContent=commitment.value?commitment.value+' months minimum':'Not specified';requiredSkills.oninput=()=>renderSkills('pvRequired',requiredSkills.value);preferredSkills.oninput=()=>renderSkills('pvPreferred',preferredSkills.value);status.onchange=()=>pvStatus.textContent=status.value+' role';let jobEditor=null;try{const {ClassicEditor,Essentials,Paragraph,Heading,Bold,Italic,Link,List,Undo}=CKEDITOR;ClassicEditor.create({attachTo:document.querySelector('#description'),licenseKey:'GPL',plugins:[Essentials,Paragraph,Heading,Bold,Italic,Link,List,Undo],toolbar:['undo','redo','|','heading','|','bold','italic','link','|','bulletedList','numberedList']}).then(editor=>{jobEditor=editor;editor.model.document.on('change:data',()=>pvDescription.innerHTML=editor.getData())}).catch(()=>{document.querySelector('#description').classList.add('control')})}catch(error){document.querySelector('#description').classList.add('control')}jobForm.addEventListener('submit',()=>{if(jobEditor)document.querySelector('#description').value=jobEditor.getData()});</script><?php require __DIR__.'/views/partials/footer.php';?>
